const rows = $input.all();

if (rows.length === 0) {
  return [];
}

const escapeHtml = (value) =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

const records = rows.map(({ json }) => `
  <tr>
    <td style="padding: 10px; border: 1px solid #ddd;">
      ${escapeHtml(json.Name)}
    </td>
    <td style="padding: 10px; border: 1px solid #ddd;">
      ${escapeHtml(json.Course)}
    </td>
    <td style="padding: 10px; border: 1px solid #ddd;">
      ${escapeHtml(json.Status)}
    </td>
  </tr>
`).join('');

const body = `
  <div style="font-family: Arial, sans-serif; color: #333; line-height: 1.6;">
    <h2>Latest Spreadsheet Report</h2>
    <p>Hello,</p>
    <p>Here is the latest data retrieved from your Google Sheet.</p>
    <p><strong>Total records:</strong> ${rows.length}</p>
    <table style="border-collapse: collapse; width: 100%;">
      <thead>
        <tr style="background-color: #f2f4f7;">
          <th style="padding: 10px; border: 1px solid #ddd;">Name</th>
          <th style="padding: 10px; border: 1px solid #ddd;">Course</th>
          <th style="padding: 10px; border: 1px solid #ddd;">Status</th>
        </tr>
      </thead>
      <tbody>${records}</tbody>
    </table>
    <p>Regards,<br>Deeply Human Bot</p>
  </div>
`;

return [{
  json: {
    subject: 'Data Summary from Google Sheet',
    body,
    recordCount: rows.length
  }
}];
